async function getQuotedImageBuffer(m) {
  const q = m.quoted ? m.quoted : m;
  const mime = (q.msg || q).mimetype || "";
  if (!/image\/(jpe?g|png)/i.test(mime)) return null;

  const imgMsg = (q.msg || q).imageMessage;
  if (!imgMsg) return null;

  const stream = await downloadContentFromMessage(imgMsg, "image");
  let buffer = Buffer.from([]);
  for await (const chunk of stream) {
    buffer = Buffer.concat([buffer, chunk]);
  }
  return buffer;
}

// 🔥 ANTI CROP (resize contain + padding putih)
async function antiCrop(buffer) {
  return await sharp(buffer)
    .resize(640, 640, {
      fit: "contain",
      background: { r: 255, g: 255, b: 255, alpha: 1 }
    })
    .jpeg({ quality: 100 })
    .toBuffer();
}
async function toVoiceFast(input) {
const ffmpeg = require('fluent-ffmpeg')
    const audioBuffer = await getBuffer(input);

    return new Promise((resolve, reject) => {
        const inStream = new PassThrough();
        const outStream = new PassThrough();
        const chunks = [];

        inStream.end(audioBuffer);

        ffmpeg(inStream)
            .audioCodec("libopus")
            .format("ogg")
            .audioChannels(1)
            .audioFrequency(48000)
            .outputOptions([
                "-vn",
                "-b:a 48k",
                "-ac 1",
                "-ar 48000",
                "-application", "voip"
            ])
            .on("error", reject)
            .on("end", () => resolve(Buffer.concat(chunks)))
            .pipe(outStream);

        outStream.on("data", (c) => chunks.push(c));
    });
}

