async function sendAlbum(Izuka, jid, medias, options = {}) {
  const userJid = Izuka.user?.id || Izuka.authState?.creds?.me?.id;
  if (!Array.isArray(medias) || medias.length < 1) {
    throw new Error("Album minimal berisi 1 media (gambar/video).");
  }

  const time = options.delay || 500;
  

  const album = await generateWAMessageFromContent(
    jid,
    {
      albumMessage: {
        expectedImageCount: medias.filter(m => m.image).length,
        expectedVideoCount: medias.filter(m => m.video).length
      }
    },
    { userJid, ...options }
  );

  await Izuka.relayMessage(jid, album.message, { messageId: album.key.id });

  for (const media of medias) {
    if (!(media.image || media.video)) continue;

    const msg = await generateWAMessage(
      jid,
      {
        ...(media.image ? { image: media.image } : {}),
        ...(media.video ? { video: media.video } : {}),
        caption: media.caption || "",
        ...options
      },
      {
        userJid,
        upload: async (readStream, opts) => {
          return await Izuka.waUploadToServer(readStream, opts);
        },
        ...options
      }
    );

    msg.message.messageContextInfo = {
      messageAssociation: {
        associationType: 1,
        parentMessageKey: album.key
      }
    };

    await Izuka.relayMessage(jid, msg.message, { messageId: msg.key.id });
    await new Promise(res => setTimeout(res, time));
  }

  return album;
}
