function normalizeNumber(number) {
    return String(number || "")
        .replace(/\D/g, "")
        .replace(/^0/, "62");
}
async function checkBotLicense() {
    try {
        const botId = normalizeNumber(botNumber.split("@")[0]);

        const { data } = await axios.get(GITHUB_LICENSE_URL, {
            timeout: 15000
        });

        const allowedBots = data.allowed_bots || [];

        return {
            status: allowedBots.includes(botId),
            botNumber: botId,
            version: data.version || "-",
            message: data.message || "-"
        };
    } catch (err) {
        return {
            status: false,
            botNumber: normalizeNumber(botNumber.split("@")[0]),
            version: "-",
            message: "Gagal menghubungkan ke database GitHub."
        };
    }
}
async function checkGithubUpdate() {
    try {
        const { data } = await axios.get(GITHUB_LICENSE_URL, {
            timeout: 15000
        });

        const githubVersion = data.version || "0.0.0";
        const localVersion = global.botVersion || "1.0.0";

        return {
            hasUpdate: githubVersion !== localVersion,
            githubVersion,
            localVersion,
            message: data.message || "Update tersedia."
        };
    } catch (err) {
        return {
            hasUpdate: false,
            githubVersion: "-",
            localVersion: global.botVersion || "1.0.0",
            message: "Gagal cek update dari GitHub."
        };
    }
}
async function uploadToGithub(filePath, content, commitMessage) {
    const url = `https://api.github.com/repos/${GITHUB_USERNAME}/${GITHUB_REPO}/contents/${filePath}`;

    let sha = null;

    try {
        const oldFile = await axios.get(url, {
            headers: {
                Authorization: `token ${GITHUB_TOKEN}`,
                Accept: "application/vnd.github.v3+json"
            }
        });

        sha = oldFile.data.sha;
    } catch {}

    const res = await axios.put(url, {
        message: commitMessage,
        content: Buffer.from(content).toString("base64"),
        branch: GITHUB_BRANCH,
        ...(sha ? { sha } : {})
    }, {
        headers: {
            Authorization: `token ${GITHUB_TOKEN}`,
            Accept: "application/vnd.github.v3+json"
        }
    });

    return res.data;
}

async function getLicenseData() {
    const rawUrl =
`https://raw.githubusercontent.com/IzukaDev0/Izuka-updste-sc/main/database/license.json?time=${Date.now()}`;

    const { data } = await axios.get(rawUrl, {
        timeout: 15000,
        headers: {
            "Cache-Control": "no-cache"
        }
    });

    return data;
}
