function resetLimitDaily(user, isPrem) {
  const limitUser = isPrem ? 10000000 : global.set.limit
  const oneDay = 24 * 60 * 60 * 1000

  // init pertama kali
  if (!isNumber(user.limit)) user.limit = limitUser
  if (!user.lastReset) user.lastReset = Date.now()

  // reset kalau lewat 24 jam
  if (Date.now() - user.lastReset >= oneDay) {
    user.limit = limitUser
    user.lastReset = Date.now()
  }
}
