//=============[ TIMER NAIK TURUN SAHAM ]===========//
let marketCronJobs = [];

function startMarketCron() {
    if (marketCronJobs.length > 0) return;

    marketCronJobs.push(
        cron.schedule("0 0 * * *", async () => {
            await resetCryptoPrice();
            await resetSahamPrice();
        }, {
            scheduled: true,
            timezone: "Asia/Jakarta"
        })
    );

    marketCronJobs.push(
        cron.schedule("0 */6 * * *", async () => {
            await resetVolumeSaham();
            await resetVolumeCrypto();
        }, {
            scheduled: true,
            timezone: "Asia/Jakarta"
        })
    );

    marketCronJobs.push(
        cron.schedule("*/10 * * * *", async () => {
            await updateSaham();
            await updateCrypto();
        }, {
            scheduled: true,
            timezone: "Asia/Jakarta"
        })
    );

    console.log("✅ Market cron aktif");
}

function stopMarketCron() {
    for (const job of marketCronJobs) {
        job.stop();
        job.destroy?.();
    }

    marketCronJobs = [];
    console.log("🛑 Market cron dimatikan");
}
