const createGuild = (guildName, creatorId) => {
    if (guilds[guildName]) {
        return reply(`Guild dengan nama ${guildName} sudah ada.`);
    }

    if (users[creatorId] && users[creatorId].guild) {
        return reply(`Anda sudah menjadi anggota guild: ${users[creatorId].guild}`);
    }

    guilds[guildName] = { leader: creatorId, members: [] };
    users[creatorId] = { guild: guildName, role: 'leader' };

    saveGuilds();
    saveUsers();

    return reply(`Guild ${guildName} berhasil dibuat!`);
};

    const listGuilds = () => {
    const guildNames = Object.keys(guilds);
    if (guildNames.length === 0) {
        return reply("Tidak ada guild yang tersedia.");
    }
    return reply(`Daftar guild yang tersedia:\n- ${guildNames.join('\n- ')}`);
};
    
const getGuildInfo = (guildName) => {
    const guild = guilds[guildName];
    if (!guild) {
        return reply(`Guild dengan nama ${guildName} tidak ditemukan.`);
    }

    const leader = guild.leader;
    const members = guild.members;

    let info = `< G U I L D - I N F O >* 

*Name: ${guildName}*\nLeader: ${leader}\n\nMembers:\n`;
    members.forEach((member, index) => {
        info += `\n${index + 1}. ${member}`;
    });

    return reply(info);
};

    
const joinGuild = (guildName, userId) => {
    const guild = guilds[guildName];
    if (!guild) {
        return reply(`Guild dengan nama ${guildName} tidak ditemukan.`);
    }

    if (users[userId] && users[userId].guild) {
        return reply(`Anda sudah menjadi anggota guild: ${users[userId].guild}`);
    }

    guild.members.push(userId);
    users[userId] = { guild: guildName, role: 'member' };

    saveGuilds();
    saveUsers();

    return reply(`Anda berhasil bergabung dengan guild ${guildName}!`);
};

const deleteGuild = (guildName, userId) => {
    const guild = guilds[guildName];
    if (!guild) {
        return reply(`Guild dengan nama ${guildName} tidak ditemukan.`);
    }

    if (guild.leader !== userId) {
        return reply(`Anda tidak memiliki izin untuk menghapus guild ini.`);
    }

    guild.members.forEach(member => {
        delete users[member];
    });

    delete users[guild.leader];
    delete guilds[guildName];

    saveGuilds();
    saveUsers();

    return reply(`Guild ${guildName} berhasil dihapus!`);
};

    const leaveGuild = (userId) => {
    const user = users[userId];
    if (!user || !user.guild) {
        return reply(`Anda tidak berada dalam guild manapun.`);
    }

    const guildName = user.guild;
    const guild = guilds[guildName];

    if (user.role === 'leader') {
        return reply(`Sebagai leader, Anda tidak bisa keluar dari guild. Anda harus menghapus guild.`);
    }

    guild.members = guild.members.filter(member => member !== userId);
    delete users[userId];

    saveGuilds();
    saveUsers();

    return reply(`Anda telah keluar dari guild ${guildName}.`);
}; 
// AUTO HANDLE KIRIM LINK SEWA (USER HARUS PUNYA SESI)
if (global.sesiLinkSewa?.[m.sender] && !isCmd) {
  const sesi = global.sesiLinkSewa[m.sender]

  // sesi kadaluarsa
  if (Date.now() > sesi.expireAt) {
    delete global.sesiLinkSewa[m.sender]
    return m.reply("Sesi sewa sudah habis. Silakan order ulang.")
  }

  // ambil link dari chat
  const link = (m.text || "").trim()
  if (!link.includes("https://chat.whatsapp.com/")) {
    return m.reply("Kirim link grup WhatsApp yang valid\n(Hanya link saja jangan ketik yang lain).")
  }

  try {
    let url = link.split("https://chat.whatsapp.com/")[1].trim()
    let inspect = await Izuka.groupGetInviteInfo(url)

    let grupJoin = (await Izuka.groupFetchAllParticipating())[inspect.id]
    let data
    let waktu = sesi.durasi

    if (!grupJoin) {
      data = await Izuka.groupAcceptInvite(url)
    } else {
      data = inspect.id
    }

    if (!data) return m.reply("Link tidak valid atau grup private.")
    if (_sewa.checkSewaGroup(data)) {
      delete global.sesiLinkSewa[m.sender]
      return m.reply("Bot sudah disewa oleh grup tersebut.")
    }

    _sewa.addSewaGroup(data, waktu)
    delete global.sesiLinkSewa[m.sender]

    await m.reply("Sewa bot berhasil ditambahkan.")

    await sleep(2000)
    let ceksewa = ms(_sewa.getSewaExpired(data) - Date.now())

    let teks = `SEWA BOT INFO

Subscribe Info:
- Grup     : ${data.split("@")[0]}
- Expired  : ${waktu.toUpperCase()}
- Countdown: ${ceksewa.days} hari, ${ceksewa.hours} jam, ${ceksewa.minutes} menit

Benefit Info:
- Feature     : 1300++
- Management  : Yes
- Request     : 1/5s
- VIP Access  : No
- Grup Priority: Yes
- Protection  : Yes
`

    await Izuka.sendMessage(data, { text: teks }, { quoted: m })

  } catch (e) {
    console.log(e)
    return m.reply("Gagal memproses link. Pastikan link valid dan bot bisa join.")
  }
} 
