// ====== 1 FUNCTION SCRAPE (PASTE SEKALI) ======

let jsonCache = null
const gB = Buffer.from("ZXRhY2xvdWQub3Jn", "base64").toString()

const headers = {
  origin: "https://v1.y2mate.nu",
  referer: "https://v1.y2mate.nu/",
  "user-agent":
    "Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/139.0.0.0 Mobile Safari/537.36",
  accept: "*/*",
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const ts = () => Math.floor(Date.now() / 1000)

async function getjson() {
  if (jsonCache) return jsonCache
  const get = await axios.get("https://v1.y2mate.nu", { headers })
  const html = get.data
  const m = /var json = JSON\.parse\('([^']+)'\)/.exec(html)
  if (!m) throw new Error("gagal ambil token json")
  jsonCache = JSON.parse(m[1])
  return jsonCache
}

function authorization(json) {
  let e = ""
  for (let i = 0; i < json[0].length; i++) {
    e += String.fromCharCode(json[0][i] - json[2][json[2].length - (i + 1)])
  }
  if (json[1]) e = e.split("").reverse().join("")
  return e.length > 32 ? e.slice(0, 32) : e
}

function extrakid(url) {
  const m =
    /youtu\.be\/([a-zA-Z0-9_-]{11})/.exec(url) ||
    /v=([a-zA-Z0-9_-]{11})/.exec(url) ||
    /\/shorts\/([a-zA-Z0-9_-]{11})/.exec(url) ||
    /\/live\/([a-zA-Z0-9_-]{11})/.exec(url)
  if (!m) throw new Error("invalid youtube url")
  return m[1]
}

async function init(json) {
  const key = String.fromCharCode(json[6])
  const url = `https://eta.${gB}/api/v1/init?${key}=${authorization(json)}&t=${ts()}`
  const res = await axios.get(url, { headers })
  if (res.data?.error && res.data.error !== 0 && res.data.error !== "0") throw res.data
  return res.data
}

/**
 * SCRAPE 1 FUNCTION
 * @param {string} videoUrl youtube url
 * @param {"mp3"|"mp4"} format
 * @returns {Promise<{id:string,title:string,format:"mp3"|"mp4",download:string}>}
 */
async function scrapeYt2mate(videoUrl, format = "mp3") {
  if (!videoUrl) throw new Error("url kosong")
  format = String(format).toLowerCase()
  if (!["mp3", "mp4"].includes(format)) throw new Error("format harus mp3/mp4")

  const json = await getjson()
  const videoId = extrakid(videoUrl)
  const initRes = await init(json)

  let res = await axios.get(
    initRes.convertURL + "&v=" + videoId + "&f=" + format + "&t=" + ts() + "&_=" + Math.random(),
    { headers }
  )

  let data = res.data
  if (data?.error && data.error !== 0) throw data

  if (data?.redirect === 1 && data?.redirectURL) {
    const r2 = await axios.get(data.redirectURL + "&t=" + ts(), { headers })
    data = r2.data
  }

  // direct selesai
  if (data?.downloadURL && !data?.progressURL) {
    return { id: videoId, title: data.title, format, download: data.downloadURL }
  }

  // polling progress
  for (;;) {
    await sleep(3000)
    const progressRes = await axios.get(data.progressURL + "&t=" + ts(), { headers })
    const p = progressRes.data
    if (p?.error && p.error !== 0) throw p
    if (p?.progress === 3) {
      return { id: videoId, title: p.title, format, download: data.downloadURL }
    }
  }
}

