async function downloadToBuffer(url) {
  const r = await axios.get(url, { responseType: "arraybuffer", headers })
  return Buffer.from(r.data)
}
    async function igTes(url) {
        try {
            const response = await axios.get(url, {
                headers: {
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
                    "Accept": "text/html",
                    "accept-language": "id-ID,id;q=0.9,en-US;q=0.8,en;q=0.7"
                },
                timeout: 10000
            })

            const $ = cheerio.load(response.data)
            let scriptJson = null

            $('script[type="application/json"]').each((_, el) => {
                const html = $(el).html()
                if (html && html.includes("xdt_api__v1__media__shortcode__web_info")) {
                    try {
                        scriptJson = JSON.parse(html)
                    } catch {}
                }
            })

            if (!scriptJson) throw "Data JSON tidak ditemukan"

            const item =
                scriptJson.require?.[0]?.[3]?.[0]?.__bbox
                    ?.require?.[0]?.[3]?.[1]?.__bbox
                    ?.result?.data
                    ?.xdt_api__v1__media__shortcode__web_info
                    ?.items?.[0]

            if (!item) throw "Item tidak ditemukan"

            if (!item.video_dash_manifest) throw "Manifest DASH tidak ditemukan"

            const parser = new XMLParser({ ignoreAttributes: false })
            const manifest = parser.parse(item.video_dash_manifest)

            const period = manifest.MPD?.Period
            if (!period) throw "Period XML tidak ditemukan"

            const sets = Array.isArray(period.AdaptationSet)
                ? period.AdaptationSet
                : [period.AdaptationSet]

            let videos = []

            sets.forEach(set => {
                if (set["@_contentType"] !== "video") return

                const reps = Array.isArray(set.Representation)
                    ? set.Representation
                    : [set.Representation]

                reps.forEach(rep => {
                    videos.push({
                        url: rep.BaseURL,
                        bandwidth: Number(rep["@_bandwidth"]) || 0,
                        resolution: `${rep["@_width"]}x${rep["@_height"]}`,
                        quality: rep["@_FBQualityLabel"] || ""
                    })
                })
            })

            videos.sort((a, b) => b.bandwidth - a.bandwidth)

            return {
                status: true,
                result: {
                    caption: item.caption?.text || "",
                    author: item.user?.username || "-",
                    video: videos[0]
                }
            }

        } catch (e) {
            return { status: false, error: e.toString() }
        }
}
    async function getFileData(buffer) {
    const { fromBuffer } = require("file-type");
    const { ext } = await fromBuffer(buffer);
    const filename = 'izuka-' + Date.now() + '.' + ext;
    return { filename, ext };
}
    async function catbox(buffer) {
    return new Promise(async (resolve, reject) => {
        try {
            const { filename } = await getFileData(buffer);
            const data = new FormData();

            data.append('reqtype', 'fileupload');
            data.append('userhash', '');
            data.append('fileToUpload', buffer, { filename });

            const api = await axios.post(
                'https://catbox.moe/user/api.php',
                data,
                {
                    headers: {
                        ...data.getHeaders(),
                        'User-Agent':
                            'Mozilla/5.0 (Android 10; Mobile; rv:131.0) Gecko/131.0 Firefox/131.0'
                    }
                }
            );

            resolve(api.data);
        } catch (err) {
            reject({ msg: 'Gomene Error Tourl' });
            console.error('Error', err);
        }
    });
}
async function pomf2(filePath) {
    const mime = require("mime-types");
    try {
        if (!fs.existsSync(filePath)) throw new Error("File tidak ditemukan");
        const contentType = mime.lookup(filePath) || "application/octet-stream";
        const fileName = path.basename(filePath);
        const ext = path.extname(filePath).toLowerCase();
        const form = new FormData();
        form.append("files[]", fs.createReadStream(filePath), {
            contentType,
            filename: fileName, // Paksa nama file tetap JPG
        });
        const response = await axios.post("https://qu.ax/upload.php", form, {
            headers: {
                ...form.getHeaders(),
            },
        });

        // Cek hasil
        if (!response.data.success || !response.data.files?.length)
            throw new Error("Upload gagal");

        return response.data.files[0].url;
    } catch (err) {
        console.error("Error:", err.message);
        return null;
    }
}




