// taruh helper ini di atas switch atau di bawah file (sekali aja)
function setupPresenceListener(conn) {
  if (global._presenceListenerSet) return;
  global._presenceListenerSet = true;

  global.onlineUsers ||= {}; // { [groupId]: { [jid]: timestamp } }

  // Presence update listener
  Izuka.ev.on("presence.update", (update) => {
    try {
      const { id, presences } = update || {};
      if (!id || !presences) return;

      // id bisa groupId atau userId tergantung event
      const isGroup = String(id).endsWith("@g.us");

      if (isGroup) {
        global.onlineUsers[id] ||= {};
        for (const [jid, p] of Object.entries(presences || {})) {
          // p itu object presence, cari status yang paling umum dipakai
          const st =
            p?.lastKnownPresence ||
            p?.presence ||
            p?.status ||
            (typeof p === "string" ? p : null);

          // available = online, composing/recording juga tanda aktif
          if (st === "available" || st === "composing" || st === "recording") {
            global.onlineUsers[id][jid] = Date.now();
          }
        }
      } else {
        // event user, sebar ke semua group yang sedang kita track
        for (const gid of Object.keys(global.onlineUsers)) {
          const p = presences?.[id];
          const st =
            p?.lastKnownPresence ||
            p?.presence ||
            p?.status ||
            (typeof p === "string" ? p : null);

          if (st === "available" || st === "composing" || st === "recording") {
            global.onlineUsers[gid] ||= {};
            global.onlineUsers[gid][id] = Date.now();
          }
        }
      }
    } catch (e) {
      // silent
    }
  });
}
  // Fallback: kalau ada pesan masuk di group, anggap "aktif chat"
global.activeChat ||= {}; // { [groupId]: { [jid]: timestamp } }

Izuka.ev.on("messages.upsert", ({ messages }) => {
  try {
    global.activeChat ||= {};
    for (const msg of messages || []) {
      const chatId = msg?.key?.remoteJid;
      const jid = msg?.key?.participant || msg?.participant;

      if (!chatId || !String(chatId).endsWith("@g.us")) continue;
      if (!jid || !String(jid).endsWith("@s.whatsapp.net")) continue;

      global.activeChat[chatId] ||= {};
      global.activeChat[chatId][jid] = Date.now();
    }
  } catch {}
});

async function showOnlineUsers(conn, m, groupId, reply) {
  global.onlineUsers ||= {};
  global.onlineUsers[groupId] ||= {};

  global.activeChat ||= {};
  global.activeChat[groupId] ||= {};

  const now = Date.now();
  const oneMinuteAgo = now - 60 * 1000;
  const fiveMinutesAgo = now - 5 * 60 * 1000;
  const tenMinutesAgo = now - 10 * 60 * 1000;
  const sixtyMinutesAgo = now - 60 * 60 * 1000;

  const cleanTag = (jid) => jid.split("@")[0].replace(/[\u200E\u200F\u2066-\u2069]/g, "");
  const uniq = (arr) => [...new Set(arr)];

  // ===== PRESENCE LIST =====
  const onlineList = [];
  const maybeList = [];

  const pres = global.onlineUsers[groupId] || {};
  for (const jid of Object.keys(pres)) {
    if (!jid.endsWith("@s.whatsapp.net")) continue;
    const t = Number(pres[jid] || 0);
    if (t > oneMinuteAgo) onlineList.push(jid);
    else if (t > fiveMinutesAgo) maybeList.push(jid);
  }

  // ===== ACTIVE CHAT LIST (lebih "ramai") =====
  const active10m = [];
  const active60m = [];

  const act = global.activeChat[groupId] || {};
  for (const jid of Object.keys(act)) {
    if (!jid.endsWith("@s.whatsapp.net")) continue;
    const t = Number(act[jid] || 0);
    if (t > tenMinutesAgo) active10m.push(jid);
    else if (t > sixtyMinutesAgo) active60m.push(jid);
  }

  // sort by last activity desc biar rapi
  const sortByTimeDesc = (arr, store) =>
    arr.sort((a, b) => (store[b] || 0) - (store[a] || 0));

  sortByTimeDesc(active10m, act);
  sortByTimeDesc(active60m, act);

  let txt = "";

  if (onlineList.length) {
    txt +=
      `┌─〔 Online (Presence ≤1m) : ${onlineList.length} 〕\n` +
      onlineList.map((v) => `├ @${cleanTag(v)}`).join("\n") +
      `\n└────\n\n`;
  }

  if (maybeList.length) {
    txt +=
      `┌─〔 Mungkin Online (Presence ≤5m) : ${maybeList.length} 〕\n` +
      maybeList.map((v) => `├ @${cleanTag(v)}`).join("\n") +
      `\n└────\n\n`;
  }

  if (active10m.length) {
    const show = active10m.slice(0, 30); // limit biar gak spam
    txt +=
      `┌─〔 Aktif Chat (≤10m) : ${active10m.length} 〕\n` +
      show.map((v) => `├ @${cleanTag(v)}`).join("\n") +
      (active10m.length > show.length ? `\n├ …dan ${active10m.length - show.length} lainnya` : "") +
      `\n└────\n\n`;
  }

  if (!active10m.length && active60m.length) {
    const show = active60m.slice(0, 30);
    txt +=
      `┌─〔 Aktif Chat (≤60m) : ${active60m.length} 〕\n` +
      show.map((v) => `├ @${cleanTag(v)}`).join("\n") +
      (active60m.length > show.length ? `\n├ …dan ${active60m.length - show.length} lainnya` : "") +
      `\n└────\n\n`;
  }

  if (!txt.trim()) return reply("Tidak ada pengguna online/aktif yang terdeteksi.");

  // mention gabungan
  const mentioned = uniq([...onlineList, ...maybeList, ...active10m, ...active60m]);

  // catatan biar user paham kenapa beda dengan header WA
  txt +=
    `_Catatan: angka "online" di header WhatsApp tidak sama dengan presence API. ` +
    `Presence sering terbatas, jadi daftar "Aktif Chat" dipakai agar lebih akurat._`;

  return Izuka.sendMessage(
    m.chat,
    { text: txt.trim(), contextInfo: { mentionedJid: mentioned } },
    { quoted: m }
  );
}
