 for (let i = 0; i < 25; i++) { 
 const x = Math.random() * 1280; 
 const y = Math.random() * 720; 
 const size = Math.random() * 8 + 2; 
 ctx.beginPath(); 
 ctx.arc(x, y, size, 0, Math.PI * 2); 
 ctx.fill(); 
 } 
 
