const GSE = "1H5tRtzsBkqXcaJ"
const PUBLIC_KEY = `-----BEGIN PUBLIC KEY-----
MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQCwlO+boC6cwRo3UfXVBadaYwcX
0zKS2fuVNY2qZ0dgwb1NJ+/Q9FeAosL4ONiosD71on3PVYqRUlL5045mvH2K9i8b
AFVMEip7E6RMK6tKAAif7xzZrXnP1GZ5Rijtqdgwh+YmzTo39cuBCsZqK9oEoeQ3
r/myG9S+9cR5huTuFQIDAQAB
-----END PUBLIC KEY-----`

const generateRandomString = (length) => {
 const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
 const bytes = crypto.randomBytes(length)
 let result = ''
 for (let i = 0; i < length; i++) {
 result += chars[bytes[i] % chars.length]
 }
 return result
}

const aesEncrypt = (plainText, key, iv) => {
 const cipher = crypto.createCipheriv('aes-128-cbc', Buffer.from(key, 'utf8'), Buffer.from(iv, 'utf8'))
 cipher.setAutoPadding(true)
 let encrypted = cipher.update(plainText, 'utf8')
 encrypted = Buffer.concat([encrypted, cipher.final()])
 return encrypted.toString('base64')
}

const aesEncryptSimple = (value, secret) => aesEncrypt(`${APP_ID}:${value}`, secret, secret)

const signx = () => {
 const timestamp = Math.floor(Date.now() / 1000)
 const nonce = Math.random().toString(36).substring(2, 12)
 const aesSecret = generateRandomString(16)
 const secretKeyHexBuffer = crypto.publicEncrypt(
 {
 key: PUBLIC_KEY,
 padding: crypto.constants.RSA_PKCS1_PADDING
 },
 Buffer.from(aesSecret, 'utf8')
 )
 const secretKeyHex = secretKeyHexBuffer.toString('hex')
 const dataToSign = `${APP_ID}:${GSE}:${timestamp}:${nonce}:${secretKeyHex}`
 const sign = aesEncrypt(dataToSign, aesSecret, aesSecret)
 return { app_id: APP_ID, t: timestamp, nonce, sign, secret_key: secretKeyHex, aesSecret }
}

const urlToBase64 = async (url) => {
 if (!url.startsWith('http://') && !url.startsWith('https://')) throw new Error('Link gambar tidak valid.')
 const { data } = await axios.get(url, { responseType: 'arraybuffer' })
 return `data:image/jpeg;base64,${Buffer.from(data).toString('base64')}`
}

async function generateBaby(fatherUrl, motherUrl, gender) {
 const { secret_key, aesSecret } = signx()
 const fp1 = aesEncryptSimple(DEVICE_ID, aesSecret)
 const wsUrl = `wss://pixnova.ai/demo-ai-baby/queue/join?fp=${DEVICE_ID}&fp1=${fp1}&x-guide=${secret_key}`

 const fatherBase64 = await urlToBase64(fatherUrl)
 const motherBase64 = await urlToBase64(motherUrl)

 return new Promise((resolve, reject) => {
 const ws = new WebSocket(wsUrl, {
 headers: {
 'Origin': 'https://pixnova.ai',
 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/135.0.0.0 Safari/537.36'
 }
 })

 ws._isResolvedOrRejected = false
 const originalResolve = resolve
 const originalReject = reject
 resolve = (v) => { if (!ws._isResolvedOrRejected) { ws._isResolvedOrRejected = true; originalResolve(v) } }
 reject = (r) => { if (!ws._isResolvedOrRejected) { ws._isResolvedOrRejected = true; originalReject(r) } }

 ws.on('open', () => console.log('🟢 WebSocket Connected'))

 ws.on('message', (data) => {
 try {
 const parsed = JSON.parse(data.toString())
 if (parsed.msg === 'send_hash') {
 const sessionHash = generateRandomString(12)
 ws.send(JSON.stringify({ session_hash: sessionHash }))
 } else if (parsed.msg === 'send_data') {
 if (!['boy', 'girl'].includes(gender)) {
 ws.close(1008, 'Invalid gender')
 return reject(new Error('Gender harus "boy" atau "girl".'))
 }
 const payload = {
 data: {
 gender,
 father_image: fatherBase64,
 mother_image: motherBase64,
 request_from: 2
 }
 }
 ws.send(JSON.stringify(payload))
 } else if (parsed.msg === 'process_completed' && parsed.success) {
 if (parsed.output?.result?.[0]) {
 const resultUrl = `https://oss-global.pixnova.ai/${parsed.output.result[0]}`
 console.log('✅ Baby generated!')
 ws.close()
 resolve(resultUrl)
 } else {
 ws.close(1008, 'Unexpected output')
 reject(new Error('Result structure unexpected.'))
 }
 } else if (parsed.success === false) {
 ws.close(1008, 'Processing error')
 reject(new Error(parsed.msg || 'Unknown processing error'))
 }
 } catch (err) {
 console.error('Parsing WebSocket error:', err)
 ws.close(1011, 'Internal error')
 reject(err)
 }
 })

 ws.on('error', err => {
 console.error('❌ WebSocket error:', err)
 reject(err)
 })

 ws.on('close', (code, reason) => {
 console.log(`🔵 WebSocket closed with code ${code}, reason: ${reason}`)
 if (code !== 1000 && !ws._isResolvedOrRejected) {
 reject(new Error(`WebSocket closed unexpectedly with code ${code}: ${reason}`))
 }
 })
 })
}
